-- Insert language specific mat_plant data in tlgnc_mat_plant_tx.
-- In the real world, these values would be initialized by SAP Material import!

prompt INSERTING into TLGNC_MAT_PLANT_TX - EN
  select mp.mat_plant_id, 'en', null, 1, systimestamp, 1, systimestamp, 1
  from tlgnc_mat_plant mp
  where (mp.mat_plant_id) not in (
    select mptx.mat_plant_id from tlgnc_mat_plant_tx mptx where mptx.lang_cd = 'en'
  )
);
update tlgnc_mat_plant_tx set chromat_reduction_txt = 'Chromat Reduction {0} months - ADN Test EN' where mat_plant_id in (-2049, -2142, -1015, -2312, -2176) and lang_cd = 'en';

